// LinkedIn — Max Points on a Line (LeetCode 149). Exact slopes as reduced integer pairs, never doubles.
public static class MaxPoints {
    public static int OnALine(int[][] points) {
        if (points == null) return 0;
        int n = points.Length;
        if (n <= 2) return n;
        int best = 0;
        for (int i = 0; i < n; i++) {
            var slopes = new Dictionary<(long Dy, long Dx), int>();
            int same = 0, local = 0;
            for (int j = i + 1; j < n; j++) {
                long dy = (long)points[j][1] - points[i][1], dx = (long)points[j][0] - points[i][0];
                if (dy == 0 && dx == 0) { same++; continue; }          // duplicate point lies on every line through i
                long g = Gcd(Math.Abs(dy), Math.Abs(dx));
                dy /= g; dx /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) { dy = -dy; dx = -dx; }   // one sign convention per direction
                int c = slopes.GetValueOrDefault((dy, dx)) + 1;
                slopes[(dy, dx)] = c;
                local = Math.Max(local, c);
            }
            best = Math.Max(best, local + same + 1);
        }
        return best;
    }

    static long Gcd(long a, long b) { while (b != 0) (a, b) = (b, a % b); return a; }
}
